fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn envelope(mixed:bool)->u128{let b=1u128<<52;let mut t=[0u128;6];let mut peak=0;for i in 0..5{for j in 0..5{t[j]+=b-1;t[j+1]+=b-2;}let w=if mixed&&i==4{48}else{52};let unit=1u128<<w;let low=(t[0]+unit-1)/unit+b-2;for j in 1..5{t[j]+=b-1;t[j+1]+=b-2;}peak=peak.max(*t.iter().max().unwrap());if w==48{t=[low+((unit-1)<<4),(t[1]/unit)+((unit-1)<<4),(t[2]/unit)+((unit-1)<<4),(t[3]/unit)+((unit-1)<<4),(t[4]/unit)+(t[5]<<4),0];}else{t[1]+=low;t=[t[1],t[2],t[3],t[4],t[5],0];}peak=peak.max(*t.iter().max().unwrap());}assert!(peak<1u128<<61);peak}
